import{_ as t,c as s,o,j as a,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易義海撮要","description":"周易義海撮要 - 周易義海撮要","frontmatter":{"title":"周易義海撮要","description":"周易義海撮要 - 周易義海撮要"},"headers":[],"relativePath":"classics/yihai-cuoyao/001.md","filePath":"classics/yihai-cuoyao/001.md"}'),i={name:"classics/yihai-cuoyao/001.md"};function r(c,e,n,p,d,u){return o(),s("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易義海撮要",tabindex:"-1"},[l("周易義海撮要 "),a("a",{class:"header-anchor",href:"#周易義海撮要","aria-label":"Permalink to “周易義海撮要”"},"​")],-1),a("p",null,"欽定四庫全書經部一",-1),a("p",null,"易類提要",-1),a("p",null,"臣等謹案：",-1),a("p",null,"周易義海撮要十二卷，宋李衡撰。衡字彥平，江都人。乾道中官秘閣修撰，尋除御史，改起居郎。事蹟具宋史本傳。先是，熙寧間，蜀人房審權病談易諸家或泥陰陽，或拘象數，乃斥去雜學異說，摘取專明人事者百家，上起鄭元，下迄王安石，編為一集，仍以孔穎達正義冠之。其有異同疑似，則各加評議，附之篇末，名曰周易義海共一百卷。衡因其義意重複，文詞冗瑣，刪削釐定，以為此書，故名曰撮要。其程頤、蘇軾、朱震三家之說，則原本未收，衡所續入。第十二卷雜論，亦衡所補綴。故婺州教授周汝能、樓鍔跋稱「卷計以百，今十有一」，蓋耑指所刪房本也。書錄解題作十卷，又傳寫之誤矣。是書成於紹興三十年，至乾道六年，衡以御史守婺州，始鋟於木。自唐以來，唯李鼎祚周易集解合漢後三十五家之說，略稱該備，繼之者審權、義海而已。然考宋史藝文志，但有衡書而無審權書。陳振孫書錄解題亦惟載殘本四卷。豈卷帙重大，當時即已散佚，抑衝書出而審權書遂廢歟？然則採擷精華，使古書不沒於後世，衡亦可謂有功矣。乾隆四十三年七月恭校上。總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易義海撮要原序：",-1),a("p",null,"易義海，熙寧間蜀人房審權所編。房謂自漢至今，專門學不啻千百家，或泥陰陽，或拘象數，或推之於互體，或失之於虛無。今於千百家內斥去雜學異說，摘取專明人事、羽翼吾道者僅百家，編為一集，仍以「正義」冠之端首，釐為百卷，目之曰周易義海。或諸家說有同異、理相疑惑者，復援父師之訓、朋友之論，輒加評議，附之篇末。衡得是書而讀之，其間尚有意義重疊、文詞冗瑣者，載加刪削，而益之以伊川、東坡、漢上之說，庶學者便於觀覽雲。紹興庚辰十一月辛巳，江都李衡彥平遂安雙清堂書。",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
